  gap: 10px;
  margin: 0;
  color: var(--text-2);
}

.detail h2 {
  margin: 8px 0 0;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
}

.kv {
  margin: 14px 0 0;
  padding: 0;
}

.kv > div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid var(--line);
}

.kv dt {
  color: var(--text-2);
}

.kv dd {
  margin: 0;
