  font-size: 13px;
}

.counts strong {
  margin-right: 4px;
  color: var(--text);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.clock {
  margin-left: auto;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}

.workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  flex: 1;
}

.primary {
  display: grid;
  align-content: start;
  gap: 16px;
  min-width: 0;
  padding: 16px 20px 32px;
}

.detail {
  min-width: 0;
  padding: 16px 20px 32px;
  background: var(--surface);
  border-top: 1px solid var(--line);
}

/* ---------- Shared blocks and severity badges ---------- */

.block {
  min-width: 0;
  padding: 14px 16px 16px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 4px;
}

.block__head {
  display: flex;
