/* Scratch test harness: runs after app.js in a copy of the page and saves results as a text download. */
(function () {
  var out = [];
  var fails = 0;
  var $ = function (id) { return document.getElementById(id); };
  var q = function (sel, root) { return (root || document).querySelector(sel); };
  var qa = function (sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); };
  var check = function (name, cond, detail) {
    if (!cond) fails++;
    out.push((cond ? 'PASS' : 'FAIL') + '  ' + name + (detail !== undefined ? '   [' + detail + ']' : ''));
  };
  var rowIds = function () { return qa('#incident-rows tr').map(function (r) { return q('.incident-link', r).textContent; }).join(','); };
  var fire = function (node, type) { node.dispatchEvent(new Event(type, { bubbles: true })); };
  var setFilter = function (id, value) {
    var node = $(id);
    node.value = value;
    fire(node, id === 'f-text' ? 'input' : 'change');
  };
  var save = function (name, text) {
    var a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([text], { type: 'text/plain' }));
    a.download = name;
    document.body.appendChild(a);
    a.click();
  };

  try {
    out.push('viewport ' + innerWidth + 'x' + innerHeight);
    var de = document.documentElement;
    out.push('scrollWidth ' + de.scrollWidth + ' clientWidth ' + de.clientWidth);
    check('no horizontal page overflow', de.scrollWidth <= de.clientWidth, de.scrollWidth + ' / ' + de.clientWidth);

    var spill = qa('body *').filter(function (e) {
      var cs = getComputedStyle(e);
      if (cs.position === 'absolute' || cs.position === 'fixed') return false;
      var r = e.getBoundingClientRect();
      return r.width > 0 && r.right > innerWidth + 0.5;
    }).slice(0, 6).map(function (e) { return e.tagName.toLowerCase() + '.' + (e.getAttribute('class') || '').split(' ')[0]; });
    check('no in-flow element extends past the viewport edge', spill.length === 0, spill.join(', '));

    // Initial content
