/*
 * Relay operations dashboard.
 *
 * The seed below is a copy of DATA.json. It is inlined rather than fetched
 * because browsers block fetch() from file:// URLs, and the page has to work
 * when it is opened straight from disk.
 */
(function () {
  'use strict';

  var DATA = {
    "metrics": [
      {"label": "Events / min", "value": "18,420", "change": "+8.2%", "direction": "up"},
      {"label": "P95 latency", "value": "184 ms", "change": "−12 ms", "direction": "down"},
      {"label": "Error rate", "value": "0.37%", "change": "+0.08 pp", "direction": "up"},
      {"label": "Queue depth", "value": "2,841", "change": "−19%", "direction": "down"}
    ],
    "throughput": [31, 28, 24, 22, 20, 23, 34, 48, 62, 71, 76, 73, 68, 72, 80, 84, 79, 75, 82, 88, 77, 63, 52, 41],
    "incidents": [
      {"id": "INC-2841", "severity": "critical", "service": "payments-api", "age": "12m", "owner": "M. Chen", "status": "investigating", "title": "Card authorization timeouts"},
      {"id": "INC-2839", "severity": "high", "service": "event-router", "age": "31m", "owner": "Unassigned", "status": "open", "title": "EU retry queue growth"},
      {"id": "INC-2837", "severity": "medium", "service": "search-index", "age": "1h 08m", "owner": "A. Silva", "status": "monitoring", "title": "Index freshness outside SLO"},
      {"id": "INC-2832", "severity": "low", "service": "webhooks", "age": "3h 42m", "owner": "R. Patel", "status": "open", "title": "Elevated partner delivery lag"}
    ]
  };

  var SEVERITY_ORDER = ['critical', 'high', 'medium', 'low'];
  var SEVERITY_LABEL = { critical: 'Critical', high: 'High', medium: 'Medium', low: 'Low' };
  var STATUS_LABEL = { open: 'Open', investigating: 'Investigating', monitoring: 'Monitoring' };
  var UNASSIGNED = 'Unassigned';
  var FILTER_KEYS = ['severity', 'service', 'status', 'owner'];
  var DEFAULT_FILTERS = { text: '', severity: 'all', service: 'all', status: 'all', owner: 'all' };

  // Whether a higher value is good news. Decides the favorable / unfavorable tone.
  var HIGHER_IS_BETTER = {
    'Events / min': true,
    'P95 latency': false,
    'Error rate': false,
    'Queue depth': false
  };

  var prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  var stackedLayout = window.matchMedia('(max-width: 1359px)');

  var incidents = DATA.incidents
    .map(function (inc) {
      return Object.assign({}, inc, { ageMinutes: parseAgeMinutes(inc.age) });
    })
    .sort(function (a, b) {
      return SEVERITY_ORDER.indexOf(a.severity) - SEVERITY_ORDER.indexOf(b.severity) ||
        b.ageMinutes - a.ageMinutes;
    });

  var state = {
    filters: Object.assign({}, DEFAULT_FILTERS),
    selectedId: incidents.length ? incidents[0].id : null,
    acked: {} // incident id -> time of acknowledgement
  };

  var rowsById = {}; // incident id -> { row, button, tag }

  /* ---------- Helpers ---------- */

  function $(id) {
    return document.getElementById(id);
  }

  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function clear(node) {
    while (node.firstChild) node.removeChild(node.firstChild);
  }

  function formatNumber(n) {
    return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  }

  // "1h 08m" -> 68, "31m" -> 31
  function parseAgeMinutes(age) {
    var match = /(?:(\d+)h)?\s*(\d+)m/.exec(age);
    if (!match) return 0;
    return Number(match[1] || 0) * 60 + Number(match[2]);
  }

  function hoursAgoLabel(hours) {
    return hours === 0 ? 'Now' : hours + 'h ago';
  }

  function pad(n) {
    return (n < 10 ? '0' : '') + n;
  }

  function clockTime(date, withSeconds) {
    var time = pad(date.getHours()) + ':' + pad(date.getMinutes());
    return withSeconds ? time + ':' + pad(date.getSeconds()) : time;
  }

  function findIncident(id) {
    return incidents.find(function (inc) { return inc.id === id; }) || null;
  }

  function severityBadge(severity) {
    return el('span', 'sev sev--' + severity, SEVERITY_LABEL[severity]);
  }

  /* ---------- Summary metrics ---------- */

  function renderMetrics() {
    var list = $('metrics');

    DATA.metrics.forEach(function (metric) {
      var up = metric.direction === 'up';
      var favorable = up === HIGHER_IS_BETTER[metric.label];

      var item = el('li', 'metric');
      item.appendChild(el('p', 'metric__label', metric.label));
      item.appendChild(el('p', 'metric__value', metric.value));

      var trend = el('p', 'metric__trend ' + (favorable ? 'trend--good' : 'trend--bad'));
      var arrow = el('span', '', up ? '▲' : '▼');
      arrow.setAttribute('aria-hidden', 'true');
      trend.appendChild(arrow);
      trend.appendChild(el('span', 'sr-only', up ? 'Up' : 'Down'));
      trend.appendChild(el('span', '', metric.change));
      trend.appendChild(el('span', '', favorable ? 'Favorable' : 'Unfavorable'));
      item.appendChild(trend);

      item.appendChild(el('p', 'metric__note', 'vs previous period'));
      list.appendChild(item);
    });
  }

  /* ---------- Throughput chart ---------- */

  function renderThroughput() {
    var values = DATA.throughput;
    var last = values.length - 1;
    var max = Math.max.apply(null, values);
    var min = Math.min.apply(null, values);
    var ceiling = Math.ceil(max / 20) * 20; // round top of the y-axis above the peak
    var total = values.reduce(function (sum, v) { return sum + v; }, 0);

    var stats = $('chart-stats');
    clear(stats);
    addStat(stats, 'Latest', values[last], '');
    addStat(stats, 'Peak', max, hoursAgoLabel(last - values.indexOf(max)));
    addStat(stats, 'Low', min, hoursAgoLabel(last - values.indexOf(min)));
    addStat(stats, 'Average', Math.round(total / values.length), '');

    var plot = $('chart-plot');
    clear(plot);

    var grid = el('div', 'chart-grid');
    grid.setAttribute('aria-hidden', 'true');
    for (var k = 1; k <= 4; k++) {
      var rule = el('div', 'chart-rule');
      rule.style.bottom = (k * 25) + '%';
      rule.appendChild(el('span', '', formatNumber(ceiling * k / 4)));
      grid.appendChild(rule);
    }
    plot.appendChild(grid);

    var bars = el('ol', 'bars');
    bars.setAttribute('aria-label', 'Hourly throughput, oldest first');
    values.forEach(function (value, i) {
      var label = hoursAgoLabel(last - i);
      var bar = el('li', 'bar');
      bar.style.setProperty('--v', String(value / ceiling));
      bar.title = label + ': ' + value;
      if (i === last) bar.classList.add('is-latest');
      bar.appendChild(el('span', 'sr-only', label + ': ' + value));
      bars.appendChild(bar);
    });
    plot.appendChild(bars);

    // One label every six hours, counted back from the latest bucket.
    var axis = $('chart-axis');
    clear(axis);
    values.forEach(function (value, i) {
      var hours = last - i;
      if (hours % 6 !== 0) return;
      var label = el('span', hours === 0 ? 'is-end' : '', hoursAgoLabel(hours));
      label.style.gridColumn = String(i + 1);
      axis.appendChild(label);
    });
  }

  function addStat(list, term, value, note) {
    var item = el('div');
    item.appendChild(el('dt', '', term));
    var description = el('dd', '', formatNumber(value));
    if (note) description.appendChild(el('small', '', note));
    item.appendChild(description);
    list.appendChild(item);
  }

  /* ---------- Filters ---------- */

  function option(value, label) {
    var node = el('option', '', label);
    node.value = value;
    return node;
  }

  function fillSelect(select, allLabel, options) {
    select.appendChild(option('all', allLabel));
    options.forEach(function (o) {
      select.appendChild(option(o.value, o.label));
    });
  }

  function fillFilterOptions() {
    fillSelect($('f-severity'), 'All severities', SEVERITY_ORDER.map(function (s) {
      return { value: s, label: SEVERITY_LABEL[s] };
    }));

    var services = incidents
      .map(function (inc) { return inc.service; })
      .filter(function (s, i, all) { return all.indexOf(s) === i; })
      .sort();
    fillSelect($('f-service'), 'All services', services.map(function (s) {
      return { value: s, label: s };
    }));

    fillSelect($('f-status'), 'All statuses', Object.keys(STATUS_LABEL).map(function (s) {
      return { value: s, label: STATUS_LABEL[s] };
    }));
  }

  function bindFilters() {
    $('f-text').addEventListener('input', function (event) {
      state.filters.text = event.target.value.trim().toLowerCase();
      applyFilters();
    });

    FILTER_KEYS.forEach(function (key) {
      $('f-' + key).addEventListener('change', function (event) {
        state.filters[key] = event.target.value;
        applyFilters();
      });
    });

    $('f-reset').addEventListener('click', resetFilters);
    $('empty-reset').addEventListener('click', resetFilters);
  }

  function filtersActive() {
    return Object.keys(DEFAULT_FILTERS).some(function (key) {
      return state.filters[key] !== DEFAULT_FILTERS[key];
    });
  }

  function resetFilters() {
    state.filters = Object.assign({}, DEFAULT_FILTERS);
    $('f-text').value = '';
    FILTER_KEYS.forEach(function (key) {
      $('f-' + key).value = 'all';
    });
    applyFilters();
    // The button that was pressed may now be hidden, so move focus to the result count.
    $('result-count').focus();
  }

  function applyFilters() {
    renderRows();
    $('f-reset').hidden = !filtersActive();
  }

  function matchesFilters(inc) {
    var f = state.filters;

    if (f.text) {
      var haystack = [inc.id, inc.title, inc.service, inc.owner, inc.age,
        SEVERITY_LABEL[inc.severity], STATUS_LABEL[inc.status]].join(' ').toLowerCase();
      if (haystack.indexOf(f.text) === -1) return false;
    }
    if (f.severity !== 'all' && inc.severity !== f.severity) return false;
    if (f.service !== 'all' && inc.service !== f.service) return false;
    if (f.status !== 'all' && inc.status !== f.status) return false;
    if (f.owner === 'assigned' && inc.owner === UNASSIGNED) return false;
    if (f.owner === 'unassigned' && inc.owner !== UNASSIGNED) return false;
    return true;
  }

  /* ---------- Incident table ---------- */

  function cell(className, label, text) {
    var td = el('td', className, text);
    td.setAttribute('role', 'cell');
    if (label) td.setAttribute('data-label', label);
    return td;
  }

  function buildRow(inc) {
    var row = el('tr');
    row.setAttribute('role', 'row');
    row.addEventListener('click', function () { selectIncident(inc.id); });

    var idCell = cell('col-id');
    var button = el('button', 'incident-link', inc.id);
    button.type = 'button';
    button.setAttribute('aria-label', inc.id + ': ' + inc.title);
    var tag = el('span', 'tag', 'Acked');
    tag.hidden = true;
    idCell.appendChild(button);
    idCell.appendChild(tag);

    var severityCell = cell('col-sev');
    severityCell.appendChild(severityBadge(inc.severity));

    [
      idCell,
      severityCell,
      cell('col-title', null, inc.title),
      cell('mono', 'Service', inc.service),
      cell('num', 'Age', inc.age),
      cell(inc.owner === UNASSIGNED ? 'is-warn' : '', 'Owner', inc.owner),
      cell('', 'Status', STATUS_LABEL[inc.status])
    ].forEach(function (td) {
      row.appendChild(td);
    });

    return { row: row, button: button, tag: tag };
  }

  function renderRows() {
    var body = $('incident-rows');
    var visible = incidents.filter(matchesFilters);

    clear(body);
    rowsById = {};
    visible.forEach(function (inc) {
      var refs = buildRow(inc);
      rowsById[inc.id] = refs;
      body.appendChild(refs.row);
    });

    var noun = incidents.length === 1 ? 'incident' : 'incidents';
    $('incident-table').hidden = visible.length === 0;
    $('empty').hidden = visible.length > 0;
    $('result-count').textContent = 'Showing ' + visible.length + ' of ' + incidents.length + ' ' + noun;
    refreshRows();
  }

  // Updates selection and acknowledgement state without rebuilding rows,
  // so a focused row button keeps focus when it is pressed.
  function refreshRows() {
    Object.keys(rowsById).forEach(function (id) {
      var refs = rowsById[id];
      var selected = id === state.selectedId;
      refs.row.classList.toggle('is-selected', selected);
      if (selected) {
        refs.button.setAttribute('aria-current', 'true');
      } else {
        refs.button.removeAttribute('aria-current');
      }
      refs.tag.hidden = !state.acked[id];
    });
  }

  function selectIncident(id) {
    state.selectedId = id;
    refreshRows();
    renderDetail();

    // On stacked layouts the detail panel sits below the table; bring it into view if it is off-screen.
    if (stackedLayout.matches) {
      var detail = $('detail');
      if (detail.getBoundingClientRect().top > window.innerHeight) {
        detail.scrollIntoView({
          block: 'start',
          behavior: prefersReducedMotion.matches ? 'auto' : 'smooth'
        });
      }
    }
  }

  /* ---------- Detail panel and acknowledgement ---------- */

  function addField(list, term, value, warn) {
    var item = el('div');
    item.appendChild(el('dt', '', term));
    item.appendChild(el('dd', warn ? 'is-warn' : '', value));
    list.appendChild(item);
  }

  function renderDetail() {
    var inc = findIncident(state.selectedId);
    var sevBadge = $('detail-sev');
    var fields = $('detail-fields');
    var ackBtn = $('ack-btn');
    clear(fields);

    if (!inc) {
      $('detail-id').textContent = '';
      sevBadge.hidden = true;
      $('detail-title').textContent = 'No incident selected';
      $('ack-state').textContent = 'Select an incident to see its details.';
      ackBtn.textContent = 'Acknowledge incident';
      ackBtn.setAttribute('aria-disabled', 'true');
      ackBtn.classList.remove('btn--done');
      return;
    }

    var ackedAt = state.acked[inc.id];

    $('detail-id').textContent = inc.id;
    sevBadge.className = 'sev sev--' + inc.severity;
    sevBadge.textContent = SEVERITY_LABEL[inc.severity];
    sevBadge.hidden = false;
    $('detail-title').textContent = inc.title;

    addField(fields, 'Service', inc.service, false);
    addField(fields, 'Owner', inc.owner, inc.owner === UNASSIGNED);
    addField(fields, 'Age', inc.age, false);
    addField(fields, 'Status', STATUS_LABEL[inc.status], false);

    $('ack-state').textContent = ackedAt
      ? 'Acknowledged by you at ' + ackedAt + '.'
      : 'Not acknowledged.';
    ackBtn.textContent = ackedAt ? 'Acknowledged' : 'Acknowledge incident';
    ackBtn.setAttribute('aria-disabled', ackedAt ? 'true' : 'false');
    ackBtn.classList.toggle('btn--done', Boolean(ackedAt));
  }

  function bindAck() {
    $('ack-btn').addEventListener('click', function () {
      var inc = findIncident(state.selectedId);
      if (!inc || state.acked[inc.id]) return;

      var time = clockTime(new Date(), true);
      state.acked[inc.id] = time;
      refreshRows();
      renderDetail();
      renderTopbar();
      $('announcer').textContent = inc.id + ' acknowledged at ' + time + '.';
    });
  }

  /* ---------- Top status bar and clock ---------- */

  function overallStatus(counts) {
    if (counts.critical) return { tone: 'critical', label: 'Critical incident open' };
    if (counts.high) return { tone: 'high', label: 'High-severity incident open' };
    if (counts.medium) return { tone: 'medium', label: 'Medium-severity incident open' };
    if (counts.low) return { tone: 'low', label: 'Low-severity incidents only' };
    return { tone: 'ok', label: 'No open incidents' };
  }

  function countItem(count, text) {
    var item = el('li');
    item.appendChild(el('strong', '', String(count)));
    item.appendChild(document.createTextNode(' ' + text));
    return item;
  }

  function renderTopbar() {
    var counts = { critical: 0, high: 0, medium: 0, low: 0 };
    var unacknowledged = 0;
    incidents.forEach(function (inc) {
      counts[inc.severity] += 1;
      if (!state.acked[inc.id]) unacknowledged += 1;
    });

    var overall = overallStatus(counts);
    var pill = $('overall');
    pill.className = 'sev sev--' + overall.tone;
    pill.textContent = overall.label;

    var list = $('counts');
    clear(list);
    SEVERITY_ORDER.forEach(function (sev) {
      list.appendChild(countItem(counts[sev], SEVERITY_LABEL[sev].toLowerCase()));
    });
    list.appendChild(countItem(unacknowledged, 'unacknowledged'));
  }

  function tickClock() {
    var now = new Date();
    var clock = $('clock');
    clock.textContent = clockTime(now, false);
    clock.setAttribute('datetime', now.toISOString());
  }

  /* ---------- Start ---------- */

  function init() {
    renderMetrics();
    renderThroughput();
    fillFilterOptions();
    bindFilters();
    bindAck();
    $('rail-count').textContent = String(incidents.length);
    renderRows();
    renderDetail();
    renderTopbar();
    tickClock();
    window.setInterval(tickClock, 15000);
  }

  init();
})();

/*
 * Relay operations control room.
 * Neutral slate surfaces, one teal accent for focus and primary actions,
 * and severity colors reserved for status. No external fonts or assets.
 */

:root {
  color-scheme: dark;

  --bg: #0d1117;
  --surface: #141a22;
  --surface-2: #1b232d;
  --line: #242d38;
  --line-strong: #374353;
  --text: #e3e8ee;
  --text-2: #a9b3bf;
  --text-3: #8d99a7;

  --accent: #58b8c8;
  --accent-ink: #061318;
  --accent-tint: rgba(88, 184, 200, 0.12);

  --good: #7ee2a0;
  --critical: #ff7b72;
  --high: #ffa657;
  --medium: #e3c35c;
  --low: #9fb4cc;

  --critical-tint: rgba(255, 123, 114, 0.15);
  --high-tint: rgba(255, 166, 87, 0.15);
  --medium-tint: rgba(227, 195, 92, 0.15);
  --low-tint: rgba(159, 180, 204, 0.15);
  --good-tint: rgba(126, 226, 160, 0.14);

  --bar: #6b7d92;
  --bar-hover: #8596aa;

  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SFMono-Regular", Menlo, Consolas, "Liberation Mono", monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.4 var(--font);
}

[hidden] {
  display: none !important;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 8px;
  top: -48px;
  z-index: 10;
  padding: 8px 12px;
  border-radius: 4px;
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 600;
  text-decoration: none;
}

.skip-link:focus {
  top: 8px;
}

.mono {
  font-family: var(--mono);
  font-size: 12.5px;
}

/* ---------- Shell: rail, top status bar, workspace ---------- */

.app {
  display: grid;
  grid-template-columns: 188px minmax(0, 1fr);
  min-height: 100vh;
}

.rail {
  position: sticky;
  top: 0;
  height: 100vh;
  padding: 14px 8px;
  background: var(--surface);
  border-right: 1px solid var(--line);
}

.rail__list {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rail__link {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 4px;
  color: var(--text-2);
  font-weight: 500;
  text-decoration: none;
}

.rail__link:hover {
  background: var(--surface-2);
  color: var(--text);
}

.rail__icon {
  width: 18px;
  height: 18px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.rail__count {
  margin-left: auto;
  padding: 0 6px;
  border-radius: 3px;
  background: var(--surface-2);
  color: var(--text-2);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.content {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 20px;
  padding: 10px 20px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: baseline;
  gap: 10px;
  min-width: 0;
}

.brand__name {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.01em;
}

.brand__sub {
  color: var(--text-2);
  font-size: 13px;
}

.counts {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--text-2);
  font-size: 13px;
}

.counts strong {
  color: var(--text);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.clock {
  margin-left: auto;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}

.workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  flex: 1;
}

.primary {
  display: grid;
  align-content: start;
  gap: 16px;
  min-width: 0;
  padding: 16px 20px 32px;
}

.detail {
  min-width: 0;
  padding: 16px 20px 32px;
  background: var(--surface);
  border-top: 1px solid var(--line);
}

/* ---------- Shared blocks and severity badges ---------- */

.block {
  min-width: 0;
  padding: 14px 16px 16px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 4px;
}

.block__head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 4px 12px;
  margin-bottom: 12px;
}

.block h2 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}

.block__meta {
  margin: 0;
  color: var(--text-2);
  font-size: 12.5px;
}

.sev {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  padding: 2px 8px;
  border-radius: 3px;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}

.sev::before {
  content: "";
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.sev--critical { color: var(--critical); background: var(--critical-tint); }
.sev--high { color: var(--high); background: var(--high-tint); }
.sev--medium { color: var(--medium); background: var(--medium-tint); }
.sev--low { color: var(--low); background: var(--low-tint); }
.sev--ok { color: var(--good); background: var(--good-tint); }

.tag {
  display: inline-block;
  margin-left: 6px;
  padding: 0 5px;
  border: 1px solid var(--accent);
  border-radius: 3px;
  color: var(--accent);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  vertical-align: 1px;
}

.is-warn {
  color: var(--medium);
}

/* ---------- Summary metrics ---------- */

.metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px;
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: 4px;
  overflow: hidden;
}

.metric {
  min-width: 0;
  margin: 0;
  padding: 12px 14px;
  background: var(--surface);
}

.metric__label {
  margin: 0;
  color: var(--text-2);
  font-size: 12.5px;
}

.metric__value {
  margin: 4px 0 6px;
  font-size: 24px;
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.15;
  font-variant-numeric: tabular-nums;
}

.metric__trend {
  display: flex;
  flex-wrap: wrap;
  gap: 0 6px;
  margin: 0;
  font-size: 12.5px;
  font-variant-numeric: tabular-nums;
}

.metric__note {
  margin: 2px 0 0;
  color: var(--text-3);
  font-size: 12px;
}

.trend--good { color: var(--good); }
.trend--bad { color: var(--high); }

/* ---------- Throughput chart (HTML bars on a CSS grid) ---------- */

.chart {
  margin: 0;
}

.chart__stats {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 28px;
  margin: 0 0 14px;
}

.chart__stats div {
  min-width: 0;
}

.chart__stats dt {
  color: var(--text-2);
  font-size: 12px;
}

.chart__stats dd {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.chart__stats small {
  margin-left: 6px;
  color: var(--text-3);
  font-size: 12px;
  font-weight: 400;
}

.chart-plot {
  position: relative;
  height: 184px;
}

.chart-grid {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 40px;
  right: 0;
  pointer-events: none;
}

.chart-rule {
  position: absolute;
  left: 0;
  right: 0;
  height: 0;
  border-top: 1px dashed var(--line-strong);
}

.chart-rule span {
  position: absolute;
  top: 0;
  right: 100%;
  margin-right: 8px;
  transform: translateY(-50%);
  color: var(--text-3);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.bars {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 40px;
  right: 0;
  display: grid;
  grid-template-columns: repeat(24, minmax(0, 1fr));
  gap: 3px;
  align-items: end;
  margin: 0;
  padding: 0;
  list-style: none;
  border-bottom: 1px solid var(--line-strong);
}

.bar {
  position: relative;
  height: calc(var(--v) * 100%);
  min-height: 2px;
  border-radius: 2px 2px 0 0;
  background: var(--bar);
}

.bar:hover {
  background: var(--bar-hover);
}

.bar.is-latest {
  background: var(--accent);
}

.chart-axis {
  position: relative;
  display: grid;
  grid-template-columns: repeat(24, minmax(0, 1fr));
  gap: 3px;
  height: 16px;
  margin: 6px 0 0 40px;
  color: var(--text-3);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.chart-axis span {
  grid-row: 1;
  justify-self: center;
  white-space: nowrap;
}

.chart-axis .is-end {
  justify-self: end;
}

/* ---------- Filters, table, empty state ---------- */

.filters {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(132px, 1fr));
  gap: 10px;
  align-items: end;
  margin-bottom: 14px;
}

.field {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.field--search {
  grid-column: 1 / -1;
}

.field label {
  color: var(--text-2);
  font-size: 12px;
}

.field input,
.field select {
  width: 100%;
  min-height: 34px;
  padding: 6px 8px;
  border: 1px solid var(--line-strong);
  border-radius: 4px;
  background: var(--bg);
  color: var(--text);
  font: inherit;
}

.field input::placeholder {
  color: var(--text-3);
}

.filters .btn {
  grid-column: 1 / -1;
  justify-self: start;
}

.btn {
  min-height: 34px;
  padding: 6px 12px;
  border: 1px solid var(--line-strong);
  border-radius: 4px;
  background: var(--surface-2);
  color: var(--text);
  font: inherit;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
}

.btn:hover {
  border-color: var(--text-2);
}

.btn--ghost {
  border-color: transparent;
  background: transparent;
  color: var(--accent);
}

.btn--primary {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 600;
}

.btn--primary:hover {
  border-color: var(--accent);
  filter: brightness(1.08);
}

.btn--done {
  border-color: var(--good);
  background: var(--good-tint);
  color: var(--good);
}

.btn[aria-disabled="true"] {
  cursor: default;
}

.incident-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.incident-table th {
  padding: 8px 10px;
  border-bottom: 1px solid var(--line-strong);
  color: var(--text-2);
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-align: left;
  text-transform: uppercase;
  white-space: nowrap;
}

.incident-table td {
  padding: 10px;
  border-bottom: 1px solid var(--line);
  vertical-align: middle;
}

.incident-table td:first-child,
.incident-table th:first-child {
  padding-left: 12px;
}

.incident-table td.col-title {
  min-width: 160px;
}

.incident-table td.col-id,
.incident-table td.col-sev,
.incident-table td.num {
  white-space: nowrap;
}

.incident-table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.incident-table th.num {
  text-align: right;
}

.incident-table tbody tr {
  cursor: pointer;
}

.incident-table tbody tr:hover {
  background: var(--surface-2);
}

.incident-table tr.is-selected {
  background: var(--accent-tint);
}

.incident-table tr.is-selected td:first-child {
  box-shadow: inset 3px 0 0 var(--accent);
}

.incident-link {
  padding: 2px 0;
  border: 0;
  background: none;
  color: var(--accent);
  font-family: var(--mono);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.incident-link:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}

.incident-link[aria-current="true"] {
  text-decoration: underline;
  text-underline-offset: 3px;
}

.empty {
  padding: 28px 16px;
  border: 1px dashed var(--line-strong);
  border-radius: 4px;
  color: var(--text-2);
  text-align: center;
}

.empty p {
  margin: 0 0 12px;
}

/* ---------- Detail panel ---------- */

.detail__eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0;
  color: var(--text-2);
}

.detail h2 {
  margin: 8px 0 0;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
}

.kv {
  margin: 14px 0 0;
  padding: 0;
}

.kv > div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid var(--line);
}

.kv dt {
  color: var(--text-2);
}

.kv dd {
  margin: 0;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.ack {
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}

.ack h3 {
  margin: 0 0 6px;
  font-size: 13px;
  font-weight: 600;
}

.ack__state {
  margin: 0 0 10px;
  color: var(--text-2);
}

/* ---------- Responsive layout ---------- */

@media (min-width: 1360px) {
  .workspace {
    grid-template-columns: minmax(0, 1fr) 352px;
  }

  .detail {
    border-top: 0;
    border-left: 1px solid var(--line);
  }
}

/* Rail becomes a top strip; the status bar and content stack under it. */
@media (max-width: 1099px) {
  .app {
    grid-template-columns: minmax(0, 1fr);
  }

  .rail {
    position: static;
    height: auto;
    padding: 6px 12px;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .rail__list {
    grid-auto-flow: column;
    justify-content: start;
    gap: 4px;
  }

  .metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 719px) {
  .topbar {
    padding: 10px 14px;
  }

  .brand__sub,
  .clock {
    display: none;
  }

  .primary {
    padding: 12px 12px 24px;
  }

  .detail {
    padding: 14px 12px 24px;
  }

  .block {
    padding: 12px;
  }

  .metric {
    padding: 10px 12px;
  }

  .metric__value {
    font-size: 21px;
  }

  .chart-plot {
    height: 160px;
  }

  /*
   * Table reflows into one card per incident. The thead stays in the
   * accessibility tree (clipped, not display:none) so every cell still
   * has a header, and explicit roles keep table semantics where
   * WebKit drops them once a table element is set to display:block.
   */
  .incident-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
  }

  .incident-table,
  .incident-table tbody {
    display: block;
    width: 100%;
  }

  .incident-table tbody tr {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px 14px;
    padding: 12px 8px;
    border-bottom: 1px solid var(--line);
  }

  .incident-table tr.is-selected {
    box-shadow: inset 3px 0 0 var(--accent);
  }

  .incident-table tr.is-selected td:first-child {
    box-shadow: none;
  }

  .incident-table td {
    display: block;
    min-width: 0;
    padding: 0;
    border: 0;
  }

  .incident-table td:first-child {
    padding-left: 0;
  }

  .incident-table td.col-sev {
    justify-self: end;
  }

  .incident-table td.col-title {
    grid-column: 1 / -1;
    min-width: 0;
    font-size: 14px;
  }

  .incident-table td.num {
    text-align: left;
  }

  .incident-table td[data-label]::before {
    display: block;
    margin-bottom: 2px;
    color: var(--text-3);
    font-size: 11px;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    content: attr(data-label);
  }

}

@media (prefers-reduced-motion: reduce) {
  * {
    scroll-behavior: auto !important;
    transition: none !important;
    animation: none !important;
  }
}

