/* Scratch layout checks, run after harness.js in the same page copy. */
(function () {
  var out = [];
  var fails = 0;
  var $ = function (id) { return document.getElementById(id); };
  var q = function (sel) { return document.querySelector(sel); };
  var qa = function (sel) { return Array.prototype.slice.call(document.querySelectorAll(sel)); };
  var check = function (name, cond, detail) {
    if (!cond) fails++;
    out.push((cond ? 'PASS' : 'FAIL') + '  ' + name + (detail !== undefined ? '   [' + detail + ']' : ''));
  };
  var save = function (name, text) {
    var a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([text], { type: 'text/plain' }));
    a.download = name;
    document.body.appendChild(a);
    a.click();
  };
  out.push('viewport ' + innerWidth + 'x' + innerHeight);

  qa('.metric').forEach(function (m, i) {
    check('metric tile ' + (i + 1) + ' content fits', m.scrollWidth <= m.clientWidth + 1, m.scrollWidth + ' / ' + m.clientWidth);
  });

  var cramped = qa('#incident-rows td').filter(function (td) {
    return getComputedStyle(td).display === 'table-cell' && td.scrollWidth > td.clientWidth + 1;
  }).map(function (td) { return td.getAttribute('data-label') || td.className; });
  check('desktop table cells fit without clipping', cramped.length === 0, cramped.join(','));

  var small = [];
  qa('body *').forEach(function (e) {
    if (e.closest('.sr-only')) return;
    var hasText = Array.prototype.some.call(e.childNodes, function (n) { return n.nodeType === 3 && n.textContent.trim(); });
    if (hasText && parseFloat(getComputedStyle(e).fontSize) < 11) small.push(e.tagName + '.' + (e.getAttribute('class') || ''));
  });
  check('no visible text below 11px', small.length === 0, small.slice(0, 6).join(', '));

  var short = qa('button, select, input').filter(function (c) { return c.getBoundingClientRect().height < 32 && c.offsetParent !== null; })
    .map(function (c) { return c.tagName + '#' + c.id + ' ' + c.getBoundingClientRect().height.toFixed(0); });
  check('form controls are at least 32px tall', short.length === 0, short.join(', '));

  var rail = q('.rail').getBoundingClientRect();
  var railMode = getComputedStyle(q('.rail')).position;
  out.push('      rail: position ' + railMode + ', ' + rail.width.toFixed(0) + 'x' + rail.height.toFixed(0));
  if (innerWidth >= 1100) check('wide: rail is a left column', rail.width < 260 && rail.height > 300, rail.width + 'x' + rail.height);
  else check('narrow: rail is a top strip', rail.width >= innerWidth - 1 && rail.height < 80, rail.width + 'x' + rail.height);

  var detail = $('detail').getBoundingClientRect();
  var primary = q('.primary').getBoundingClientRect();
  if (innerWidth >= 1360) check('wide: detail panel sits beside the table', detail.left >= primary.right - 1 && detail.top < primary.top + 60, 'detail.left ' + detail.left.toFixed(0) + ' primary.right ' + primary.right.toFixed(0));
  else check('stacked: detail panel sits below the incidents block', detail.top >= primary.bottom - 1, 'detail.top ' + detail.top.toFixed(0) + ' primary.bottom ' + primary.bottom.toFixed(0));

  var cols = getComputedStyle(q('.metrics')).gridTemplateColumns.split(' ').length;
  out.push('      metric columns: ' + cols);
  check('metric grid is 4 columns on wide, 2 on narrow', innerWidth >= 1100 ? cols === 4 : cols === 2, cols);

  var tile = q('.metrics').getBoundingClientRect();
  check('metrics grid stays inside the viewport', tile.right <= innerWidth + 0.5, tile.right.toFixed(0));

  var bars = q('.bars').getBoundingClientRect();
  var axis = q('.chart-axis').getBoundingClientRect();
  check('chart axis labels fit horizontally', qa('.chart-axis span').every(function (s) {
    var r = s.getBoundingClientRect();
    return r.left >= axis.left - 1 && r.right <= innerWidth + 0.5;
  }));
  out.push('      bars width ' + bars.width.toFixed(0) + ', plot height ' + bars.height.toFixed(0));

  out.push('');
  out.push(fails === 0 ? 'ALL LAYOUT CHECKS PASSED' : fails + ' LAYOUT CHECK(S) FAILED');
  save('layout-' + innerWidth + 'x' + innerHeight + '.txt', out.join('\n') + '\n');
})();
EOF
