/*
 * Relay operations control room.
 * Neutral slate surfaces, one teal accent for focus and primary actions,
 * and severity colors reserved for status. No external fonts or assets.
 */

:root {
  color-scheme: dark;

  --bg: #0d1117;
  --surface: #141a22;
  --surface-2: #1b232d;
  --line: #242d38;
  --line-strong: #374353;
  --text: #e3e8ee;
  --text-2: #a9b3bf;
  --text-3: #8d99a7;

  --accent: #58b8c8;
  --accent-ink: #061318;
  --accent-tint: rgba(88, 184, 200, 0.12);

  --good: #7ee2a0;
  --critical: #ff7b72;
  --high: #ffa657;
  --medium: #e3c35c;
  --low: #9fb4cc;

  --critical-tint: rgba(255, 123, 114, 0.15);
  --high-tint: rgba(255, 166, 87, 0.15);
  --medium-tint: rgba(227, 195, 92, 0.15);
  --low-tint: rgba(159, 180, 204, 0.15);
  --good-tint: rgba(126, 226, 160, 0.14);

  --bar: #6b7d92;
  --bar-hover: #8596aa;

  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SFMono-Regular", Menlo, Consolas, "Liberation Mono", monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.4 var(--font);
}

[hidden] {
  display: none !important;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 8px;
  top: -48px;
  z-index: 10;
  padding: 8px 12px;
  border-radius: 4px;
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 600;
  text-decoration: none;
}

.skip-link:focus {
  top: 8px;
}

.mono {
  font-family: var(--mono);
  font-size: 12.5px;
}

/* ---------- Shell: rail, top status bar, workspace ---------- */

.app {
  display: grid;
  grid-template-columns: 188px minmax(0, 1fr);
  min-height: 100vh;
}

.rail {
  position: sticky;
  top: 0;
  height: 100vh;
  padding: 14px 8px;
  background: var(--surface);
  border-right: 1px solid var(--line);
}

.rail__list {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rail__link {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 4px;
  color: var(--text-2);
  font-weight: 500;
  text-decoration: none;
}

.rail__link:hover {
  background: var(--surface-2);
  color: var(--text);
}

.rail__icon {
  width: 18px;
  height: 18px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.rail__count {
  margin-left: auto;
  padding: 0 6px;
  border-radius: 3px;
  background: var(--surface-2);
  color: var(--text-2);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.content {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 20px;
  padding: 10px 20px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: baseline;
  gap: 10px;
  min-width: 0;
}

.brand__name {
  margin: 0;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.01em;
}

.brand__sub {
  color: var(--text-2);
  font-size: 13px;
}

.counts {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--text-2);
  font-size: 13px;
}

.counts strong {
  color: var(--text);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.clock {
  margin-left: auto;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}

.workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  flex: 1;
}

.primary {
  display: grid;
  align-content: start;
  gap: 16px;
  min-width: 0;
  padding: 16px 20px 32px;
}

.detail {
  min-width: 0;
  padding: 16px 20px 32px;
  background: var(--surface);
  border-top: 1px solid var(--line);
}

/* ---------- Shared blocks and severity badges ---------- */

.block {
  min-width: 0;
  padding: 14px 16px 16px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 4px;
}

.block__head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 4px 12px;
  margin-bottom: 12px;
}

.block h2 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}

.block__meta {
  margin: 0;
  color: var(--text-2);
  font-size: 12.5px;
}

.sev {
  display: inline-flex;
  align-items: center;
