/* Scratch test harness: runs after app.js in a copy of the page and saves results as a text download. */
(function () {
  var out = [];
  var fails = 0;
  var $ = function (id) { return document.getElementById(id); };
  var q = function (sel, root) { return (root || document).querySelector(sel); };
  var qa = function (sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); };
  var check = function (name, cond, detail) {
    if (!cond) fails++;
    out.push((cond ? 'PASS' : 'FAIL') + '  ' + name + (detail !== undefined ? '   [' + detail + ']' : ''));
  };
  var rowIds = function () { return qa('#incident-rows tr').map(function (r) { return q('.incident-link', r).textContent; }).join(','); };
  var fire = function (node, type) { node.dispatchEvent(new Event(type, { bubbles: true })); };
  var setFilter = function (id, value) {
    var node = $(id);
    node.value = value;
    fire(node, id === 'f-text' ? 'input' : 'change');
  };
  var save = function (name, text) {
    var a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([text], { type: 'text/plain' }));
    a.download = name;
    document.body.appendChild(a);
    a.click();
  };

  try {
    out.push('viewport ' + innerWidth + 'x' + innerHeight);
    var de = document.documentElement;
    out.push('scrollWidth ' + de.scrollWidth + ' clientWidth ' + de.clientWidth);
    check('no horizontal page overflow', de.scrollWidth <= de.clientWidth, de.scrollWidth + ' / ' + de.clientWidth);

    var spill = qa('body *').filter(function (e) {
      var cs = getComputedStyle(e);
      if (cs.position === 'absolute' || cs.position === 'fixed') return false;
      var r = e.getBoundingClientRect();
      return r.width > 0 && r.right > innerWidth + 0.5;
    }).slice(0, 6).map(function (e) { return e.tagName.toLowerCase() + '.' + (e.getAttribute('class') || '').split(' ')[0]; });
    check('no in-flow element extends past the viewport edge', spill.length === 0, spill.join(', '));

    // Initial content
    check('four metrics rendered', qa('#metrics li').length === 4);
    var tones = qa('.metric__trend').map(function (p) { return p.className.indexOf('trend--good') >= 0 ? 'good' : 'bad'; }).join(',');
    check('trend tones: events up=good, latency down=good, error up=bad, queue down=good', tones === 'good,good,bad,good', tones);
    var trendText = qa('.metric__trend').map(function (p) { return p.textContent.replace(/\s+/g, ' ').trim(); });
    out.push('      trend text: ' + trendText.join(' | '));

    check('24 bars rendered and latest flagged', qa('#chart-plot .bar').length === 24 && qa('.bar.is-latest').length === 1);
    var bars = qa('#chart-plot .bar');
    var plotH = q('#chart-plot .bars').getBoundingClientRect().height;
    var peakRatio = bars[19].getBoundingClientRect().height / plotH;
    check('bar height scales to ceiling 100 (value 88 -> 0.88 of plot)', Math.abs(peakRatio - 0.88) < 0.02, peakRatio.toFixed(3));
    var lowRatio = bars[4].getBoundingClientRect().height / plotH;
    check('bar height scales (value 20 -> 0.20 of plot)', Math.abs(lowRatio - 0.20) < 0.02, lowRatio.toFixed(3));
    check('y-axis labels', qa('.chart-rule span').map(function (s) { return s.textContent; }).join(',') === '25,50,75,100');
    check('x-axis labels', qa('#chart-axis span').map(function (s) { return s.textContent; }).join(',') === '18h ago,12h ago,6h ago,Now');
    var dds = qa('#chart-stats dd').map(function (d) { return d.textContent.replace(/\s+/g, ' ').trim(); });
    out.push('      chart stats: ' + dds.join(' | '));
    check('chart stats: latest 41, peak 88 4h ago, low 20 19h ago, average 57',
      dds.join('|') === '41|88 4h ago|20 19h ago|57', dds.join('|'));
    check('bar sr text sample', q('#chart-plot .bar:nth-child(20) .sr-only').textContent === '4h ago: 88', q('#chart-plot .bar:nth-child(20) .sr-only').textContent);

    check('rows in severity then age order', rowIds() === 'INC-2841,INC-2839,INC-2837,INC-2832', rowIds());
    check('initial result count', $('result-count').textContent === 'Showing 4 of 4 incidents', $('result-count').textContent);
    check('initial detail is first critical incident', $('detail-title').textContent === 'Card authorization timeouts');
    check('rail count is 4', $('rail-count').textContent === '4');
    check('overall status label', $('overall').textContent === 'Critical incident open', $('overall').textContent);
    out.push('      counts: ' + $('counts').textContent.replace(/\s+/g, ' ').trim());
    check('initially 4 unacknowledged', $('counts').textContent.indexOf('4 unacknowledged') >= 0);
    check('select options populated', qa('#f-service option').map(function (o) { return o.value; }).join(',') === 'all,event-router,payments-api,search-index,webhooks');
    check('severity options populated', qa('#f-severity option').map(function (o) { return o.value; }).join(',') === 'all,critical,high,medium,low');
    check('reset button hidden at start', $('f-reset').hidden === true);
    check('ack button starts aria-disabled=false for selected', $('ack-btn').getAttribute('aria-disabled') === 'false');

    var mobile = innerWidth < 720;
    var desktopTable = q('#incident-table');
    if (mobile) {
      check('mobile: rows become grid cards', getComputedStyle(q('#incident-rows tr')).display === 'grid');
      check('mobile: thead clipped but present', getComputedStyle(q('.incident-table thead')).position === 'absolute' && q('.incident-table thead th') !== null);
      var lbl = getComputedStyle(q('#incident-rows td[data-label="Owner"]'), '::before').content;
      check('mobile: owner label generated', lbl.indexOf('Owner') >= 0, lbl);
    } else {
      check('desktop: real table layout', getComputedStyle(desktopTable).display === 'table');
    }

    // Selection
    qa('#incident-rows .incident-link')[1].click();
    check('selecting a row updates detail title', $('detail-title').textContent === 'EU retry queue growth', $('detail-title').textContent);
    check('only selected button has aria-current', qa('[aria-current="true"]').length === 1 && q('[aria-current="true"]').textContent === 'INC-2839');
    check('selected row has is-selected class', q('#incident-rows tr.is-selected').textContent.indexOf('INC-2839') >= 0);
    check('unassigned owner flagged', q('#detail-fields .is-warn') !== null && q('#detail-fields .is-warn').textContent === 'Unassigned');
    check('detail fields: service, owner, age, status', qa('#detail-fields dd').map(function (d) { return d.textContent; }).join('|') === 'event-router|Unassigned|31m|Open', qa('#detail-fields dd').map(function (d) { return d.textContent; }).join('|'));

    // Acknowledge
    $('ack-btn').click();
    var ack1 = $('ack-state').textContent;
    check('acknowledge records time', /^Acknowledged by you at \d{2}:\d{2}:\d{2}\.$/.test(ack1), ack1);
    check('acknowledge button shows done and aria-disabled', $('ack-btn').textContent === 'Acknowledged' && $('ack-btn').getAttribute('aria-disabled') === 'true');
    check('ack tag only on INC-2839 row', qa('#incident-rows .tag').filter(function (t) { return !t.hidden; }).length === 1 && q('#incident-rows tr .tag:not([hidden])').closest('tr').textContent.indexOf('INC-2839') >= 0);
    check('topbar unacknowledged count drops to 3', $('counts').textContent.indexOf('3 unacknowledged') >= 0, $('counts').textContent.replace(/\s+/g, ' ').trim());
    check('announcer message set', $('announcer').textContent.indexOf('INC-2839 acknowledged at') === 0, $('announcer').textContent);
    $('ack-btn').click();
    check('second acknowledge is a no-op', $('ack-state').textContent === ack1);
    check('ack survives re-render (filter change)', (setFilter('f-status', 'open'), $('ack-btn').textContent === 'Acknowledged' && !q('#incident-rows .tag:not([hidden])') === false));
    $('f-reset').click();

    // Filters
    setFilter('f-text', 'webhook');
    check('text filter narrows to one row', rowIds() === 'INC-2832', rowIds());
    check('result count after filter', $('result-count').textContent === 'Showing 1 of 4 incidents', $('result-count').textContent);
    check('clear button visible while filtered', $('f-reset').hidden === false);
    setFilter('f-text', 'PAYMENTS');
    check('text search is case-insensitive and matches service', rowIds() === 'INC-2841', rowIds());
    setFilter('f-text', '');
    check('clearing search restores rows', rowIds().split(',').length === 4);
    setFilter('f-severity', 'low');
    setFilter('f-owner', 'unassigned');
    check('no match shows empty state and hides table', rowIds() === '' && !$('empty').hidden && $('incident-table').hidden);
    check('empty copy', $('empty').textContent.indexOf('No incidents match these filters.') >= 0);
    check('result count reads zero', $('result-count').textContent === 'Showing 0 of 4 incidents', $('result-count').textContent);
    $('empty-reset').click();
    check('empty-state reset restores rows', rowIds().split(',').length === 4);
    check('empty-state reset clears select values', $('f-severity').value === 'all' && $('f-owner').value === 'all');
    check('empty-state reset hides clear button', $('f-reset').hidden === true);
    check('focus moves to result count after reset', document.activeElement && document.activeElement.id === 'result-count', document.activeElement && document.activeElement.id);

    setFilter('f-owner', 'unassigned');
    check('owner=unassigned returns INC-2839 only', rowIds() === 'INC-2839', rowIds());
    setFilter('f-owner', 'assigned');
    check('owner=assigned excludes unassigned', rowIds().indexOf('INC-2839') === -1 && rowIds().split(',').length === 3, rowIds());
    setFilter('f-owner', 'all');
    setFilter('f-service', 'search-index');
    check('service filter', rowIds() === 'INC-2837', rowIds());
    setFilter('f-service', 'all');
    setFilter('f-status', 'monitoring');
    check('status filter', rowIds() === 'INC-2837', rowIds());
    $('f-reset').click();
    check('reset from filter bar restores rows', rowIds().split(',').length === 4);

    // Selection persists when the selected incident is filtered out
    qa('#incident-rows .incident-link')[0].click();
    setFilter('f-severity', 'low');
    check('detail keeps selected incident while it is filtered out', $('detail-title').textContent === 'Card authorization timeouts');
    $('f-reset').click();

    // Keyboard: pressing Enter on a focused ID button is a click on the button
    var target = qa('#incident-rows .incident-link')[2];
    target.focus();
    target.click();
    check('ID button selects and focus stays on it', document.activeElement === target && $('detail-title').textContent === 'Index freshness outside SLO', document.activeElement && document.activeElement.textContent);

    out.push('');
    out.push(fails === 0 ? 'ALL CHECKS PASSED' : fails + ' CHECK(S) FAILED');
  } catch (err) {
    out.push('EXCEPTION: ' + err.message + ' @ ' + (err.stack || '').split('\n').slice(0, 3).join(' | '));
  }
  save('results-' + innerWidth + 'x' + innerHeight + '.txt', out.join('\n') + '\n');
})();
